24	  it('accepts list_sessions with optional limit and before, strips unknown fields, and rejects malformed options', () => {
25	    const beforeIso = {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'};
26	    const beforeEpoch = {updatedAt: 1767225600000, sessionId: 'a'.repeat(128)};
27	    const valid = {
